import 'package:cloud_firestore/cloud_firestore.dart';
import '../../../services/goals/goal_repository.dart';
import '../../../services/memory/memory_repository.dart';
class AurenDailyReview{final int activeGoals,completedGoals,enabledMemories,averageProgress;final String headline,focus;final DateTime generatedAt;const AurenDailyReview({required this.activeGoals,required this.completedGoals,required this.enabledMemories,required this.averageProgress,required this.headline,required this.focus,required this.generatedAt});Map<String,dynamic> toMap()=>{'activeGoals':activeGoals,'completedGoals':completedGoals,'enabledMemories':enabledMemories,'averageProgress':averageProgress,'headline':headline,'focus':focus,'generatedAt':Timestamp.fromDate(generatedAt.toUtc())};}
class DailyReviewService{final FirebaseFirestore _db;final GoalRepository _goals;final MemoryRepository _memory;DailyReviewService({FirebaseFirestore? firestore,GoalRepository? goals,MemoryRepository? memory}):_db=firestore??FirebaseFirestore.instance,_goals=goals??GoalRepository(),_memory=memory??MemoryRepository();
Future<AurenDailyReview> build(String uid)async{final goals=await _goals.watch(uid).first;final memories=await _memory.watch(uid).first;final active=goals.where((g)=>g.status=='active').toList();final completed=goals.where((g)=>g.status=='completed').length;final enabled=memories.where((m)=>m.enabled).length;final avg=active.isEmpty?0:active.fold<int>(0,(s,g)=>s+g.progress)~/active.length;final focus=active.isEmpty?'اختر هدفًا واحدًا لليوم.':active.first.title;final headline=active.isEmpty?'مراجعة اليوم جاهزة: لا يوجد هدف نشط حاليًا.':'مراجعة اليوم: لديك ${active.length} أهداف نشطة ومتوسط تقدم ${avg}%.';
final review=AurenDailyReview(activeGoals:active.length,completedGoals:completed,enabledMemories:enabled,averageProgress:avg,headline:headline,focus:focus,generatedAt:DateTime.now());await _db.collection('users').doc(uid).collection('daily_reviews').doc('current').set(review.toMap());return review;}}